const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const gaul = ee.FeatureCollection('FAO/GAUL/2015/level1')
      .filter(ee.Filter.eq('ADM0_NAME', 'China'))
      .filter(ee.Filter.stringContains('ADM1_NAME', 'Shanghai'));
    let geomSource = 'GAUL';
    let shGeom;
    if (gaul.size().getInfo() > 0) {
      shGeom = gaul.geometry();
    } else {
      // Fallback: bounding box around Shanghai municipality
      geomSource = 'BBox';
      shGeom = ee.Geometry.Polygon(
        [[[120.3, 31.6],[120.3, 30.5],[122.3, 30.5],[122.3, 31.6],[120.3, 31.6]]],
        null, false
      );
    }

    // Periods (inclusive end -> use exclusive end with +1 day)
    const p1 = {start: '2020-02-10', end: '2020-02-26'}; // Feb 10–25
    const p2 = {start: '2020-04-20', end: '2020-05-13'}; // Apr 20–May 12

    function getNO2CollectionWithFallback(start, end, geom) {
      const offl = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
        .filterDate(start, end)
        .filterBounds(geom);
      const offlSize = offl.size().getInfo();
      if (offlSize > 0) return {col: offl, dataset: 'OFFL', size: offlSize};
      const nrti = ee.ImageCollection('COPERNICUS/S5P/NRTI/L3_NO2')
        .filterDate(start, end)
        .filterBounds(geom);
      const nrtiSize = nrti.size().getInfo();
      if (nrtiSize > 0) return {col: nrti, dataset: 'NRTI', size: nrtiSize};
      return {col: null, dataset: 'NONE', size: 0};
    }

    function maskNO2(img) {
      const qa = img.select('qa_value');
      const good = qa.gte(0.75);
      return img.updateMask(good);
    }

    function computeStats(col, geom) {
      const band = 'tropospheric_NO2_column_number_density';
      const maskedMean = col.map(maskNO2).select(band).mean();
      // Valid pixel count
      const countDict = maskedMean.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: geom,
        scale: 3000,
        maxPixels: 1e9
      });
      const pix = countDict.get(band).getInfo();
      if (!pix || pix === 0) return {pixels: 0, mean: null};
      const meanDict = maskedMean.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: geom,
        scale: 3000,
        maxPixels: 1e9
      });
      const meanVal = meanDict.get(band).getInfo();
      return {pixels: pix, mean: meanVal};
    }

    // Acquire collections
    const c1 = getNO2CollectionWithFallback(p1.start, p1.end, shGeom);
    const c2 = getNO2CollectionWithFallback(p2.start, p2.end, shGeom);

    if (c1.size === 0 || c2.size === 0) {
      console.log(`Geom: ${geomSource}`);
      console.log(`P1 Images: ${c1.size}, Dataset: ${c1.dataset}`);
      console.log(`P2 Images: ${c2.size}, Dataset: ${c2.dataset}`);
      console.log('C1: Empty Collection (No images found in date/location for one or both comparison points).');
      console.log('C1: Empty Collection (No images found in date/location for one or both comparison points).'.split('\n').slice(-1)[0]); // ensure single final tag line
      return;
    }

    // Compute stats
    const s1 = computeStats(c1.col, shGeom);
    const s2 = computeStats(c2.col, shGeom);

    // Output concise stats
    console.log(`Geom: ${geomSource}`);
    console.log(`P1 (${p1.start} to ${p1.end}): Images=${c1.size}, Dataset=${c1.dataset}`);
    console.log(`P2 (${p2.start} to ${p2.end}): Images=${c2.size}, Dataset=${c2.dataset}`);
    console.log(`P1 Valid Pixels: ${s1.pixels}`);
    console.log(`P2 Valid Pixels: ${s2.pixels}`);

    if (s1.pixels === 0 || s2.pixels === 0) {
      console.log('C2: No Valid Pixels (Images exist, but after cloud masking/processing, 0 pixels remain).');
      console.log('C2: No Valid Pixels (Images exist, but after cloud masking/processing, 0 pixels remain).'.split('\n').slice(-1)[0]);
      return;
    }

    // Validate means
    const v1 = s1.mean;
    const v2 = s2.mean;
    console.log(`P1 Mean NO2 (mol/m^2): ${v1}`);
    console.log(`P2 Mean NO2 (mol/m^2): ${v2}`);

    if (
      v1 === null || v2 === null ||
      isNaN(v1) || isNaN(v2) ||
      v1 <= 0 || v2 <= 0 ||
      v1 > 0.01 || v2 > 0.01
    ) {
      console.log('C3: Calculation Failure (Result is None/NaN/invalid range).');
      console.log('C3: Calculation Failure (Result is None/NaN/invalid range).'.split('\n').slice(-1)[0]);
      return;
    }

    const delta = v2 - v1;
    console.log(`Delta (P2 - P1): ${delta}`);

    // Final Answer
    const eps = 1e-8;
    if (delta > eps) {
      console.log('A: Yes');
    } else {
      console.log('B: No');
    }
  } catch (err) {
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
